<?php
namespace Tests\Feature;use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\{Employee,ZktecoAttendanceEvent};
class ZktecoIntegrationTest extends TestCase {use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed();config(['zkteco.enabled'=>true,'zkteco.bridge_token'=>'test-bridge-token','zkteco.require_employee_mapping'=>false,'zkteco.primary_device.id'=>'zkteco-primary','zkteco.primary_device.timezone'=>'Asia/Damascus']);$this->postJson('/api/auth/setup',['name'=>'Admin','username'=>'admin','password'=>'Test-Password123!','password_confirmation'=>'Test-Password123!'])->assertCreated();}
 private function employee(string $id='E-ZK',string $enroll='82'){return $this->postJson('/api/employees',['id'=>$id,'name'=>'Fingerprint Employee','department'=>'الموارد البشرية','zktecoEnrollmentNumber'=>$enroll,'zktecoExempt'=>false,'jobTitle'=>'QA role','hireDate'=>'2025-01-01','workdayHours'=>8])->assertCreated();}
 private function punch(string $key,string $time,string $enroll='82',array $extra=[]){return $this->withToken('test-bridge-token')->postJson('/api/integrations/zkteco/events',array_merge(['eventKey'=>$key,'deviceId'=>'zkteco-primary','enrollmentNumber'=>$enroll,'deviceTime'=>$time,'verifyMethod'=>1,'attState'=>255,'workCode'=>0,'isInvalid'=>0,'source'=>'event'],$extra));}
 public function test_bridge_requires_dedicated_token():void{$this->employee();$this->postJson('/api/integrations/zkteco/events',['deviceId'=>'zkteco-primary'])->assertUnauthorized();}
 public function test_ingestion_is_idempotent_and_derives_first_last_punch():void{$this->employee();$this->punch('evt-1','2026-10-01 08:00:00')->assertAccepted()->assertJsonPath('data.processingStatus','processed');$this->punch('evt-1','2026-10-01 08:00:00')->assertAccepted()->assertJsonPath('data.status','duplicate');$this->punch('evt-2','2026-10-01 17:03:00')->assertAccepted();$this->assertCount(2,ZktecoAttendanceEvent::all());$r=collect(Employee::find('E-ZK')->data['attendanceRecords'])->firstWhere('source','zkteco');$this->assertSame('08:00',$r['inTime']);$this->assertSame('17:03',$r['outTime']);$this->assertFalse($r['needsHrReview']);}
 public function test_repeat_within_sixty_seconds_is_preserved_but_ignored():void{$this->employee();$this->punch('evt-a','2026-10-01 08:00:00')->assertAccepted();$this->punch('evt-b','2026-10-01 08:00:35')->assertAccepted();$e=ZktecoAttendanceEvent::where('event_key','evt-b')->first();$this->assertTrue($e->ignored_for_attendance);$this->assertSame('repeat_within_60_seconds',$e->ignore_reason);$r=collect(Employee::find('E-ZK')->data['attendanceRecords'])->firstWhere('source','zkteco');$this->assertNull($r['outTime']);}
 public function test_unknown_enrollment_is_preserved_then_replayed_after_mapping():void{$this->employee('E-ZK','82');$res=$this->punch('unknown-1','2026-10-01 09:00:00','300')->assertAccepted()->assertJsonPath('data.processingStatus','unmapped');$id=$res->json('data.eventId');$this->postJson('/api/zkteco/mappings',['deviceId'=>'zkteco-primary','employeeId'=>'E-ZK','enrollmentNumber'=>'300'])->assertCreated();$this->postJson('/api/zkteco/events/'.$id.'/replay')->assertOk()->assertJsonPath('data.processing_status','processed');}
 public function test_employee_can_be_explicitly_exempt():void{$this->postJson('/api/employees',['id'=>'E-X','name'=>'Exempt Employee','department'=>'الموارد البشرية','zktecoExempt'=>true,'jobTitle'=>'QA role','hireDate'=>'2025-01-01'])->assertCreated();$this->assertTrue(Employee::find('E-X')->data['zktecoExempt']);}
}
